using Ap2Master.Domain;

namespace Ap2Master.Content;

public static partial class TeachingFacts
{
    private static readonly DateTime V = new(2026, 9, 2, 0, 0, 0, DateTimeKind.Utc);

    private static TeachingFact Teil3(TopicDef t) => t.Id switch
    {
        "t3" => F(t, "WiSo prüft wirtschaftliche und rechtliche Grundbildung: Ausbildung, Arbeitsrecht, SV, Unternehmen, Kaufvertrag, Steuern, Konjunktur.",
            "IHK-typisch 30 gebundene Aufgaben in 60 Minuten. Genau lesen, Operator und Anzahl der richtigen Antworten beachten. Zeitabhängige Zahlen nur mit Gültigkeit.",
            "Eine Simulation enthält BBiG-Textform, Mutterschutzfristen, AG-Zuständigkeit 10.000 € und Kartellverbot.",
            "Falle: Alte Skriptzahlen (Schriftform-only, 5.000 € AG, 14 Wochen Mutterschutz nach Geburt) als aktuell anzukreuzen."),
        "t3-bbig" => F(t, "Das BBiG regelt die Berufsausbildung: Vertrag, Pflichten, Probezeit, Prüfung, Niederschrift/Abfassung, Verzeichnis.",
            "Neben BBiG gelten JArbSchG, NachwG, AGG. IHK ist zuständige Stelle. BVaDiG hat 2024 u. a. die Form der Vertragsabfassung modernisiert.",
            "Ausbildungsvertrag mit Probezeit, Berufsziel FIAE, Vergütung, Urlaub.",
            "Falle: BBiG mit BetrVG oder BGB-Arbeitsvertrag ohne Spezialregeln gleichzusetzen.",
            null, "BBiG"),
        "t3-av-inhalt" => F(t, "§ 11 BBiG nennt wesentliche Inhalte: Art, sachliche und zeitliche Gliederung, Beginn/Dauer, Probezeit, Arbeitszeit, Vergütung, Urlaub, Kündigung, Tarif/BV, Ausbildungsnachweis-Form u. a.",
            "Die Liste ist nicht frei erfindbar. Änderungen ebenfalls abfassen und übermitteln.",
            "Vergütung nach Lehrjahr, 30 Tage Urlaub, Probezeit 3 Monate, Berufsschule.",
            "Falle: Nur 'Name und Unterschrift' als ausreichenden Inhalt.",
            null, "§ 11 BBiG"),
        "t3-textform" => F(t, "Seit der BBiG-Änderung durch das BVaDiG (ab 1.8.2024) sind die wesentlichen Inhalte nach § 11 BBiG in Textform (§ 126b BGB) abzufassen, nicht mehr zwingend in der klassischen Schriftform mit eigenhändiger Unterschrift.",
            "Elektronische Übermittlung so, dass Speichern und Ausdrucken möglich ist. Empfang ist nachzuweisen; Azubi muss den Empfang bestätigen. Aufbewahrung der Abfassung und des Empfangsnachweises: drei Jahre nach Ablauf des Jahres, in dem das Ausbildungsverhältnis endete. Kündigung bleibt ein anderes Rechtsinstitut mit eigener Form.",
            "PDF-Vertrag per E-Mail, lesbar, speicherbar, Empfangsbestätigung, Eintrag ins Verzeichnis.",
            "Falle: 'Nur handschriftliche Unterschrift macht den Ausbildungsvertrag wirksam' als aktuelle Regel.",
            null, "§ 11 BBiG, § 126b BGB", true, new DateOnly(2024, 8, 1), null, V, VerificationStatus.CorrectedFromSource, "Gesetzestext vorrangig vor Skripten", "§ 11 BBiG Textform"),
        "t3-rechte-pflichten" => F(t, "Ausbildende: ausbilden, ausbilden lassen durch geeignetes Personal, Freistellung Berufsschule/Prüfung, Zeugnis, Vergütung. Azubi: Lernpflicht, Sorgfalt, Weisungen, Berufsschule, Ausbildungsnachweis, Betriebsordnung.",
            "§§ 13–16 BBiG. Berichtsheft ist Pflicht, nicht nur 'nice to have'.",
            "Freistellung am Prüfungstag, Nachweise führen.",
            "Falle: Azubi dürfe Berufsschule nach Gutdünken schwänzen, weil Betrieb Vorrang hat – unzutreffend.",
            null, "§§ 13 ff. BBiG"),
        "t3-probezeit" => F(t, "Die Probezeit im Berufsausbildungsverhältnis muss mindestens einen Monat und darf höchstens vier Monate betragen (§ 20 BBiG).",
            "Während der Probezeit kann schriftlich ohne Angabe von Gründen gekündigt werden, die Kündigungsform bleibt einzuhalten. Nach der Probezeit gelten andere Kündigungsregeln.",
            "Vereinbarung 3 Monate Probezeit, Kündigung in Woche 8 in der rechtlich vorgesehenen Form.",
            "Falle: Probezeit 6 Monate wie oft im allgemeinen Arbeitsrecht analog anzuwenden.",
            null, "§ 20 BBiG"),
        "t3-kuendigung-azubi" => F(t, "Kündigung des Berufsausbildungsvertrags unterliegt § 22 BBiG: in der Probezeit ohne Angabe von Gründen, danach nur aus wichtigem Grund ohne Frist oder vom Azubi mit Frist bei Berufsaufgabe/Wechsel. Die Form der Kündigung ist nicht mit der Textform der Vertragsabfassung nach § 11 gleichzusetzen.",
            "Schriftformerfordernis der Kündigung nach geltendem § 22 BBiG beachten – nicht 'Textform reicht analog § 11'. Zustellung und Vertretung Minderjähriger.",
            "Nach Probezeit fristlose Kündigung nur bei wichtigem Grund, z. B. schwerer Pflichtverletzung, unter Formvorschrift.",
            "Falle: Vertragsabfassung in Textform und Kündigung in denselben Topf werfen.",
            null, "§ 22 BBiG", false, null, null, V, VerificationStatus.CorrectedFromSource, "Gesetzestext", "Kündigung ≠ Vertragsabfassung"),
        "t3-ende-ausbildung" => F(t, "Das Berufsausbildungsverhältnis endet mit Ablauf der vereinbarten Dauer. Bestehen der Abschlussprüfung vor Ablauf: Ende mit Bekanntgabe des Ergebnisses durch den Prüfungsausschuss (§ 21 Abs. 2 BBiG), nicht 'irgendwann am Prüfungstag' ohne Bekanntgabe.",
            "Nichtbestehen: auf Verlangen Verlängerung bis zur nächstmöglichen Wiederholungsprüfung, max. ein Jahr (§ 21 Abs. 3 BBiG).",
            "Prüfung am 12.6. bestanden, Ergebnis offiziell am 18.6. bekannt gegeben → Ende 18.6.",
            "Falle: Ende automatisch am Kalendertag der schriftlichen Prüfung ohne Bekanntgabe.",
            null, "§ 21 BBiG", false, null, null, V, VerificationStatus.CorrectedFromSource),
        "t3-nichtbestehen" => F(t, "Bei Nichtbestehen kann der Azubi Verlängerung verlangen, bis die nächste mögliche Wiederholungsprüfung stattfindet, höchstens um ein Jahr.",
            "Wiederholungsmöglichkeiten der Prüfung nach BBiG/Prüfungsordnung. Betrieb und Berufsschule bleiben eingebunden.",
            "Nicht bestanden im Sommer → Verlängerung bis Winterprüfung, wenn verlangt.",
            "Falle: Automatisches unbefristetes Weiterlaufen ohne Verlangen.",
            null, "§ 21 Abs. 3 BBiG"),
        "t3-jarbschg" => F(t, "Das JArbSchG schützt Beschäftigte unter 18: Arbeitszeit, Pausen, Freizeit, Urlaub, Nachtarbeit, gefährliche Arbeiten, Untersuchungen.",
            "Gilt neben BBiG. Erwachsene Azubis fallen nicht unter JArbSchG-Arbeitszeiten.",
            "16-jährige Azubi: max. 8 Stunden/Tag, 40/Woche grundsätzlich.",
            "Falle: JArbSchG auf 19-jährige Azubis anzuwenden.",
            null, "JArbSchG"),
        "t3-azubi-arbeitszeit" => F(t, "Minderjährige: grundsätzlich höchstens 8 Stunden täglich und 40 Stunden wöchentlich; Berufsschule wird angerechnet. Ausnahmen eng und gesetzlich bestimmt.",
            "5-Tage-Woche angestrebt. Schicht- und Samstagsarbeit mit Grenzen.",
            "Berufsschultag 6 Stunden wird auf Arbeitszeit angerechnet, Betrieb danach begrenzt.",
            "Falle: 10-Stunden-Tag analog Erwachsene nach ArbZG ohne JArbSchG.",
            null, "§§ 8 ff. JArbSchG"),
        "t3-pausen" => F(t, "Bei Minderjährigen: bei mehr als 4,5 bis 6 Stunden mindestens 30 Minuten Pause, über 6 Stunden 60 Minuten. Pausen nach spätestens 4,5 Stunden.",
            "Pausen sind Arbeitsunterbrechung, keine Arbeitszeit. Lage im Betrieb planen.",
            "7-Stunden-Tag → 60 Minuten Pause.",
            "Falle: Erwachsenen-Pausenregelung (ArbZG 30/45 Min) ungeprüft auf 16-Jährige.",
            null, "§ 11 JArbSchG"),
        "t3-nachtarbeit" => F(t, "Nachtarbeit Minderjähriger ist grundsätzlich unzulässig (20–6 Uhr, mit Branchenausnahmen z. B. Gastronomie enger gesetzlich). Schichtgrenzen beachten.",
            "Ausnahmen stehen im Gesetz, nicht im Belieben des Ausbilders.",
            "Keine regelmäßige Beschäftigung 22 Uhr in der Systemgastronomie ohne gesetzliche Ausnahmeprüfung.",
            "Falle: 'In der IT-Hotline dürfen 17-Jährige immer Nachtschicht.'",
            null, "§ 14 JArbSchG"),
        "t3-urlaub-minderjaehrig" => F(t, "Urlaub Minderjähriger hängt vom Alter zu Beginn des Kalenderjahres ab: mindestens 30 Werktage unter 16, 27 unter 17, 25 unter 18 (Werktage, nicht pauschal Urlaubstage Mo–Fr ohne Umrechnung).",
            "Werktage = Mo–Sa in der gesetzlichen Zählung. Tarif kann günstiger sein.",
            "15-Jährige zu Jahresbeginn: 30 Werktage.",
            "Falle: Einheitlich 24 Werktage BUrlG ohne JArbSchG.",
            null, "§ 19 JArbSchG"),
        "t3-erstuntersuchung" => F(t, "Vor Aufnahme der Beschäftigung Minderjähriger ist eine Erstuntersuchung erforderlich, Nachuntersuchung nach einem Jahr, Bescheinigung dem Arbeitgeber vorlegen.",
            "Ohne gültige Bescheinigung Beschäftigungsverbot. Kostenregelung gesetzlich.",
            "Bescheinigung vor Ausbildungsstart einholen.",
            "Falle: Untersuchung als freiwilliges Angebot ohne Rechtsfolge.",
            null, "§§ 32 ff. JArbSchG"),
        "t3-arbeitsvertrag" => F(t, "Der allgemeine Arbeitsvertrag ist ein gegenseitiger Vertrag: Arbeit gegen Vergütung, Treue- und Fürsorgepflichten, Weisungsrecht im Rahmen von Gesetz, Tarif, BV, Vertrag.",
            "Nachweispflichten, Probezeit oft bis 6 Monate, Kündigungsfristen § 622 BGB, Sonderregeln TzBfG, KSchG, MuSchG.",
            "Volljährige Fachkraft 40 h, Probezeit 6 Monate, Frist 4 Wochen zum 15. oder Monatsende in den ersten 2 Jahren.",
            "Falle: Azubi-Probezeit 1–4 Monate unbesehen auf alle Arbeitsverhältnisse zu übertragen."),
        "t3-nachwg" => F(t, "Das Nachweisgesetz verpflichtet den Arbeitgeber, wesentliche Vertragsbedingungen in Textform niederzulegen und zu übermitteln (digitale Nachweise unter Voraussetzungen).",
            "Nicht identisch mit der Wirksamkeit des Arbeitsvertrags (der kann mündlich entstehen), aber Ordnungswidrigkeit möglich. Fristen für die Aushändigung/Übermittlung beachten.",
            "Textform-Nachweis über Vergütung, Arbeitsort, Arbeitszeit binnen gesetzlicher Frist.",
            "Falle: Ohne schriftlichen Nachweis existiere kein Arbeitsverhältnis.",
            null, "NachwG"),
        "t3-probezeit-av" => F(t, "Im allgemeinen Arbeitsverhältnis ist die Probezeit vertraglich, üblich bis 6 Monate; in dieser Zeit oft verkürzte Kündigungsfrist (§ 622 Abs. 3 BGB: zwei Wochen), sofern vereinbart.",
            "KSchG-Wartezeit 6 Monate ist verwandt, aber nicht identisch mit Probezeit.",
            "Kündigung am 3. Monat mit 2-Wochen-Frist, wenn Probezeit vereinbart.",
            "Falle: Probezeit automatisch 4 Monate wie BBiG."),
        "t3-kuendigungsfristen" => F(t, "§ 622 BGB: grundlegend 4 Wochen zum 15. oder zum Monatsende; in der Probezeit 2 Wochen möglich; danach verlängern sich die Fristen für den Arbeitgeber nach Betriebszugehörigkeit. Tarifvertrag kann abweichen.",
            "Arbeitnehmerfrist bleibt oft 4 Wochen zum 15./Ende, sofern nicht Tarif/Vertrag anders (gleichwertig/länger beim AN je nach Gestaltung).",
            "8 Jahre Betriebszugehörigkeit → längere AG-Frist laut Tabelle § 622 Abs. 2.",
            "Falle: Immer 4 Wochen für beide Seiten ohne Tabelle.",
            null, "§ 622 BGB"),
        "t3-ord-ausserord" => F(t, "Ordentliche Kündigung wahrt Fristen und (falls KSchG) soziale Rechtfertigung. Außerordentliche (§ 626 BGB) bei wichtigem Grund ohne Frist, meist innerhalb von 2 Wochen nach Kenntnis, unverzüglich Anhörung BR.",
            "Abmahnung typisch bei steuerbarem Verhalten vor ordentlicher verhaltensbedingter Kündigung, nicht immer bei außerordentlich schwerer Pflichtverletzung.",
            "Diebstahl kann außerordentlich sein; einmal 5 Min. zu spät in der Regel nicht.",
            "Falle: Jede Kündigung sei fristlos möglich.",
            null, "§ 626 BGB, KSchG"),
        "t3-aenderungskuendigung" => F(t, "Änderungskündigung kündigt das alte Verhältnis und bietet Fortsetzung zu geänderten Bedingungen an. Annahme, Ablehnung, Annahme unter Vorbehalt mit Kündigungsschutzklage.",
            "Unterliegt Kündigungsregeln. Nicht bloß 'Versetzung' ohne Rechtsgrundlage.",
            "Angebot: andere Abteilung, geringere Vergütung, Frist zur Annahme.",
            "Falle: Als jederzeitiges Direktionsrecht ohne Kündigung."),
        "t3-aufhebung" => F(t, "Der Aufhebungsvertrag beendet einvernehmlich. Sperrzeit beim Arbeitslosengeld droht, Abfindung ist Verhandlungssache, AGB-Kontrolle und Widerruf nur in engen Fällen.",
            "Schriftform oft vereinbart/üblich; Bedingung klar regeln (Zeugnis, Resturlaub, Freistellung).",
            "Aufhebung zum 31.3. mit Abfindung, Sperrzeitrisiko belehren.",
            "Falle: Aufhebung = Kündigung durch den Arbeitgeber."),
        "t3-ksg" => F(t, "KSchG gilt u. a. nach 6 Monaten Wartezeit in Betrieben mit in der Regel mehr als 10 Arbeitnehmern (Schwellen, Zählregeln beachten). Dann nur sozial gerechtfertigte Kündigungen.",
            "Kleinbetriebsschutz, Wartezeit, Klagefrist 3 Wochen (§ 4 KSchG) sind klassische Fallen.",
            "11 AN, 8 Monate beschäftigt → KSchG-Prüfung der sozialen Rechtfertigung.",
            "Falle: KSchG in jedem Mini-Betrieb ab Tag 1.",
            null, "KSchG"),
        "t3-kuendigungsgruende" => F(t, "Personenbedingt: in der Person liegende Gründe (Krankheit unter strengen Voraussetzungen). Verhaltensbedingt: steuerbares Pflichtwidriges, oft nach Abmahnung. Betriebsbedingt: dringende betriebliche Erfordernisse plus Sozialauswahl.",
            "Drei Gruppen nicht mischen. Beweislast und Verhältnismäßigkeit.",
            "Umsatzrückgang mit Wegfall des Arbeitsplatzes, Sozialauswahl nach Alter, Unterhalt, Betriebszugehörigkeit, Schwerbehinderung.",
            "Falle: 'Der Chef mag ihn nicht' als betriebsbedingt."),
        "t3-sonderkuendigungsschutz" => F(t, "Besonderer Kündigungsschutz z. B. für Schwangere/nach Entbindung (MuSchG), Elternzeit, Schwerbehinderte (Zustimmung Integrationsamt), Betriebsratsmitglieder, Datenschutzbeauftragte, Auszubildende nach Probezeit (wichtigem Grund).",
            "Unwissenheit schützt den Arbeitgeber nicht. Anzeigefristen (z. B. Schwangerschaft).",
            "Kündigung einer Schwangeren ohne zulässige Behörde unwirksam.",
            "Falle: Sonderkündigungsschutz nur 'wenn der AG es wusste' pauschal – Kenntnisregeln genau prüfen, nicht leugnen.",
            null, "MuSchG, SGB IX, BetrVG"),
        "t3-befristung" => F(t, "Befristung nach TzBfG: mit Sachgrund oder kalendermäßig sachgrundlos unter engen Voraussetzungen (u. a. max. 2 Jahre, höchstens dreimal verlängerbar, grundsätzlich kein Anschluss an Vorbezug beimselben AG – Details aktuell halten).",
            "Schriftform der Befristungsabrede vor Arbeitsaufnahme. Unwirksame Befristung führt zu unbefristetem Verhältnis.",
            "Sachgrundlos 12 Monate, einmal verlängert um 6, schriftlich vor Start.",
            "Falle: Mündliche Befristung 'bis Projektende' ohne Schrift.",
            null, "TzBfG"),
        "t3-tarif" => F(t, "Tarifverträge werden zwischen tariffähigen Parteien geschlossen und regeln Arbeitsbedingungen. Bindung: beiderseitige Tarifbindung oder Allgemeinverbindlichkeit, Bezugnahme im Arbeitsvertrag.",
            "Normative und schuldrechtliche Teile. Günstigkeitsprinzip gegenüber Arbeitsvertrag.",
            "ITler im tarifgebundenen Haus: Entgelttabelle TV.",
            "Falle: Jeder TV gelte automatisch für die ganze Branche ohne AVM oder Bindung."),
        "t3-tarifarten" => F(t, "Entgelttarif: Löhne/Gehälter. Manteltarif: allgemeine Bedingungen (AZ, Urlaub, Kündigungsfristen). Rahmentarif: Eingruppierungsrahmen. Firmentarif vs. Verbandstarif.",
            "Laufzeit, Nachwirkung § 4 Abs. 5 TVG nach Ablauf bis Neuabschluss, soweit nicht neu vereinbart.",
            "Mantel: 30 Tage Urlaub; Entgelt: Gruppe 9, Stufe 2.",
            "Falle: Mantel mit Betriebsvereinbarung gleichsetzen."),
        "t3-tarifautonomie" => F(t, "Tarifautonomie (Art. 9 Abs. 3 GG, TVG): Koalitionen regeln Arbeits- und Wirtschaftsbedingungen grundsätzlich ohne staatlichen Inhaltsdiktat, staatlicher Rahmen bleibt (Gesetze, AVM).",
            "Streikrecht als Mittel, kein Selbstzweck. Mindestlohn setzt Untergrenze.",
            "Gewerkschaft und Arbeitgeberverband verhandeln TV ohne Ministerium als Vertragspartei.",
            "Falle: Der Staat setze alle Löhne per TV fest.",
            null, "Art. 9 Abs. 3 GG, TVG"),
        "t3-guenstigkeit" => F(t, "Günstigkeitsprinzip: vom Tarif abweichende Arbeitsvertragsregelungen gelten, wenn sie für die Beschäftigten günstiger sind. Ungünstigere weichen dem TV (bei Bindung).",
            "Vergleich objektbezogen, nicht 'insgesamt irgendwie nett'. Öffnungsklauseln erlauben Abweichung auch nach unten, wenn der TV es gestattet.",
            "Vertrag 32 Urlaubstage > TV 30 → 32 bleiben.",
            "Falle: AG kann einseitig 'ungünstiger, aber Job sicher' ohne Rechtsgrund setzen."),
        "t3-frieden" => F(t, "Während der Laufzeit eines TV gilt relative Friedenspflicht für die geregelten Materien: keine Arbeitskampfmaßnahmen darüber.",
            "Nach Ablauf bzw. für nicht geregelte Themen kann Kampf erlaubt sein. Wildcat-Streiks bleiben rechtswidrig.",
            "Entgelttarif läuft: kein Streik um dasselbe Entgelt.",
            "Falle: Absolute Friedenspflicht für immer, zu allen Themen."),
        "t3-arbeitskampf" => F(t, "Arbeitskampf: Streik (AN-Seite) und Aussperrung (AG-Seite) unter engen Voraussetzungen: tariffähige Führung, Friedenspflicht beendet, Ultima Ratio, Verhältnismäßigkeit.",
            "Beamte haben kein Streikrecht. Flashmob-Grenzen. Lohnanspruch entfällt grundsätzlich für Streikzeit (außer wild/rechtswidrig anders).",
            "Gewerkschaft ruft nach gescheiterter Verhandlung zum Streik auf.",
            "Falle: Jeder 'Krankfeiern'-Tag sei legaler Streik."),
        "t3-streik-aussperrung" => F(t, "Streik: planmäßige gemeinschaftliche Arbeitsniederlegung. Aussperrung: planmäßiges Ausschließen von AN als Kampfmittel, in DE an enge Grenzen (u. a. Abwehraussperrung) gebunden.",
            "Aussperrung ist nicht das Alltagsinstrument. Streikbruchprämien rechtlich umstritten/kontextabhängig – in der Prüfung Grunddefinitionen zuerst.",
            "Warnstreik 2 Stunden vs. unbefristeter Erzwingungsstreik.",
            "Falle: Aussperrung = jederzeitiges Hausverbot ohne Kampfbezug."),
        "t3-betriebsrat" => F(t, "Der Betriebsrat ist die gewählte Interessenvertretung der Arbeitnehmer im Betrieb nach BetrVG, nicht der Ersatz für Gewerkschaften (die bleiben tariffähig).",
            "Wahl ab 5 regelmäßig Beschäftigten. Amtszeit, Kündigungsschutz, Kosten trägt AG.",
            "Betrieb 80 MA wählt BR, der in personellen Maßnahmen mitwirkt.",
            "Falle: BR = Gewerkschaftsfiliale, die TVs abschließt.",
            null, "BetrVG"),
        "t3-betrvg" => F(t, "BetrVG regelt Betriebsverfassung: BR, JAV, Wirtschaftsausschuss, Mitwirkung/Mitbestimmung in sozialen, personellen, wirtschaftlichen Angelegenheiten.",
            "Gilt nicht für Tendenzbetriebe uneingeschränkt, nicht für öffentliche Verwaltung (dort BPersVG/LPersVG).",
            "§ 87 soziale Mitbestimmung (Beginn/Ende AZ, Überwachungstechnik …).",
            "Falle: BetrVG in der Behörde 1:1 ohne Personalvertretungsrecht.",
            null, "BetrVG"),
        "t3-mitbestimmung" => F(t, "Mitbestimmung: echte Entscheidungsteilhabe (Einigungsstelle), Mitwirkung: Information/Anhörung. § 87 Abs. 1 BetrVG (soziale Angelegenheiten) ist Kern der echten Mitbestimmung, soweit nicht gesetzlich/tariflich geregelt.",
            "Personell: Anhörung bei Kündigung (§ 102) – ohne Anhörung unwirksam. Einstellung, Versetzung.",
            "Einführung von Keylogger-Software mitbestimmungspflichtig.",
            "Falle: 'Der BR darf nur Kaffee kochen und Feste planen.'",
            null, "§§ 87, 99, 102 BetrVG"),
        "t3-betriebsvereinbarung" => F(t, "Betriebsvereinbarungen sind schriftliche Normenverträge BR–Arbeitgeber, unmittelbar und zwingend für die Betriebsangehörigen, soweit der BR zuständig ist.",
            "Keine Regelung von Arbeitsentgelten, die üblicherweise dem TV vorbehalten sind (§ 77 Abs. 3) – Tarifvorrang. Günstigkeit vs. TV gesondert.",
            "BV zur Zeiterfassung und Homeoffice-Rahmen.",
            "Falle: BV darf den TV unterbieten, weil 'näher am Betrieb'.",
            null, "§ 77 BetrVG"),
        "t3-tarifvorrang" => F(t, "Tarifvorrang: Arbeitsentgelte und sonstige Arbeitsbedingungen, die durch TV geregelt sind oder üblicherweise geregelt werden, können nicht Gegenstand einer BV sein (§ 77 Abs. 3 BetrVG), Öffnungsklauseln ausgenommen.",
            "Schützt die Tarifautonomie. Unzulässige BV-Teile unwirksam.",
            "TV Entgelt existiert → BR darf keine abweichende Entgelttabelle per BV setzen.",
            "Falle: BR und AG 'kreativ' den TV per BV ersetzen."),
        "t3-sv" => F(t, "Die gesetzliche Sozialversicherung ist eine öffentlich-rechtliche Pflichtversicherung in fünf Zweigen, überwiegend beitragsfinanziert, mit Solidarprinzip.",
            "Arbeitnehmer und Arbeitgeber teilen viele Beiträge, UV allein AG, PV-Zuschläge differenziert. Rechengrößen jährlich.",
            "FIAE-Azubi ist typisch SV-pflichtig in KV, PV, RV, AV; UV über die BG.",
            "Falle: SV mit privater Zusatzversicherung gleichzusetzen."),
        "t3-fuenf-zweige" => F(t, "Fünf Zweige: Kranken (KV), Pflege (PV), Renten (RV), Arbeitslosen (AV), Unfallversicherung (UV).",
            "Träger unterschiedlich (Krankenkassen, Pflegekassen, RV-Träger, BA, Berufsgenossenschaften). Leistungen und Finanzierung unterscheiden sich.",
            "Wegeunfall → UV, nicht KV als erstem zuständigem Zweig (UV vor KV bei Arbeitsunfall).",
            "Falle: Sechs Zweige oder UV vergessen."),
        "t3-kv-pv-rv-av-uv" => F(t, "KV: Krankheit, Prävention. PV: Pflegebedürftigkeit. RV: Alter, Erwerbsminderung, Hinterbliebene (Umlage, Generationenvertrag). AV: Arbeitslosigkeit, Förderung. UV: Arbeitsunfall, Berufskrankheit, Prävention.",
            "Zuständigkeitsabgrenzung in Aufgaben häufig. UV unabhängig von Verschulden des Versicherten (außer grobe Fälle).",
            "Sturz auf dem direkten Arbeitsweg → UV.",
            "Falle: Arbeitsunfall primär über private Haftpflicht des Chefs statt UV."),
        "t3-versicherungstraeger" => F(t, "Trägerbeispiele: gesetzliche Krankenkassen, Pflegekassen bei den KK, Deutsche Rentenversicherung, Bundesagentur für Arbeit, gewerbliche Berufsgenossenschaften / Unfallkassen.",
            "I-T-Betriebe oft VBG oder zuständige BG. Minijob-Zentrale ist kein fünfter Zweig.",
            "Azubi-Unfall anmelden bei der zuständigen BG.",
            "Falle: Finanzamt als SV-Träger."),
        "t3-beitragsfinanzierung" => F(t, "KV, PV, RV, AV: Beiträge vom Arbeitsentgelt bis zur jeweiligen BBG, paritätisch geteilt mit Ausnahmen (PV-Zuschlag Kinderlose, UV nur AG, Zusatzbeitrag KV hälftig).",
            "2026: allgemeiner KV-Satz 14,6 %, durchschnittlicher Zusatzbeitrag 2,9 % (kassenindividuell abweichend), PV 3,6 % plus 0,6 %-Punkte Kinderlosenzuschlag ab 23, RV 18,6 %, AV 2,6 %. UV Umlage AG.",
            "Brutto 3.000 €: Beiträge bis BBG voll, da unter allen Grenzen.",
            "Falle: Alle Sätze hälftig und UV vom AN.",
            null, "SGB IV–VII, BMG Zusatzbeitrag 2026", true, new DateOnly(2026, 1, 1), new DateOnly(2026, 12, 31), V),
        "t3-bbg" => F(t, "Die Beitragsbemessungsgrenze deckelt das beitragspflichtige Entgelt. 2026 bundeseinheitlich: RV/AV 101.400 €/Jahr (8.450 €/Monat), KV/PV 69.750 €/Jahr (5.812,50 €/Monat).",
            "Nicht mit der JAEG/Versicherungspflichtgrenze verwechseln. West/Ost-Unterschiede in RV/AV entfielen ab 2025.",
            "Gehalt 10.000 €/Monat: RV nur bis 8.450 € bemessen.",
            "Falle: Eine einzige BBG für alle Zweige oder 2024er West/Ost-Werte als aktuell.",
            null, "SVBezGrV 2026", true, new DateOnly(2026, 1, 1), new DateOnly(2026, 12, 31), V, VerificationStatus.Verified, "SVBezGrV 2026", "BBG 2026"),
        "t3-jaeg" => F(t, "Die Jahresarbeitsentgeltgrenze (Versicherungspflichtgrenze) entscheidet über die KV-Versicherungspflicht in der GKV. 2026 allgemeine JAEG 77.400 €, besondere JAEG 69.750 €.",
            "Wer regelmäßig darüber liegt, kann unter Voraussetzungen in die PKV wechseln – nicht automatisch müssen. BBG ≠ JAEG.",
            "Jahresgehalt 80.000 € > 77.400 € → Versicherungsfreiheit in der GKV möglich, nicht zwingend PKV.",
            "Falle: JAEG mit BBG gleichsetzen oder 73.800 € (2025) als 2026er Wert.",
            null, "§ 6 SGB V, SVBezGrV 2026", true, new DateOnly(2026, 1, 1), new DateOnly(2026, 12, 31), V),
        "t3-generationenvertrag" => F(t, "Generationenvertrag: die erwerbstätige Generation finanziert per Umlage die Renten der Älteren, erwartet später selbst Leistungen der Nachfolgenden.",
            "Demografie belastet das Modell → Nachhaltigkeitsfaktor, Rente mit Altersgrenzen, ergänzende kapitalgedeckte Vorsorge politisch ergänzend.",
            "Beitrag der 2026 Beschäftigten zahlt 2026er Renten.",
            "Falle: Jeder Euro Beitrag sei auf einem persönlichen Sparkonto der RV wie eine Lebensversicherung."),
        "t3-umlage" => F(t, "Umlageverfahren: laufende Einnahmen finanzieren laufende Ausgaben (RV, auch UV-Umlage der BG, Pflege/KV im Kern).",
            "Kapitaldeckung sammelt Vermögen. Mischformen existieren. UV: Arbeitgeberumlage nach Gefahrklasse.",
            "BG-Beitrag hängt vom Entgelt und der Gefahrklasse, nicht vom privaten Sparplan des AN.",
            "Falle: Umlage = jeder spart sein Risiko selbst auf einem Depot."),
        "t3-unfall" => F(t, "Arbeitsunfälle ereignen sich bei der versicherten Tätigkeit. Wegeunfälle auf dem direkten Weg nach/von der Arbeit, mit Abweg- und Umwegregeln.",
            "Unfallanzeige, UV-Träger zahlt Heilbehandlung, Verletztengeld, Rente. Haftung des Unternehmers gegenüber Versicherten oft beschränkt.",
            "Sturz auf dem direkten Heimweg nach Feierabend.",
            "Falle: Jeder Freizeitunfall am Wochenende sei Wegeunfall."),
        "t3-bk" => F(t, "Berufskrankheiten sind in der BK-Liste (BKV) bezeichnete Krankheiten, die durch die berufliche Einwirkung verursacht sind; im Einzelfall wie BK anerkennbar.",
            "Anzeige durch Arzt/AG. Lärmschwerhörigkeit, Haut, Asbest historisch typisch – aktuelle Liste nicht auswendig alle Nummern, aber Prinzip.",
            "Langjährige Lösemittel-Exposition, Hautarzt zeigt BK an.",
            "Falle: Jede Krankheit eines Beschäftigten sei BK."),
        "t3-arbschutz" => F(t, "Arbeitsschutz: AG organisiert Sicherheit und Gesundheit (ArbSchG, ArbStättV, DGUV). Ziel: Prävention, nicht nur Versicherung hinterher.",
            "Gefährdungsbeurteilung Pflicht. Unterweisung, PSA als letzte Stufe nach TOP.",
            "Bildschirmarbeitsplatz, Fluchtwege, Unterweisung Homeoffice-Anteile.",
            "Falle: Arbeitsschutz = nur Feuerlöscher kaufen.",
            null, "ArbSchG"),
        "t3-gbu" => F(t, "Die Gefährdungsbeurteilung ermittelt und bewertet Gefährdungen und legt Maßnahmen fest, Dokumentation, Fortschreibung bei Änderungen.",
            "Psychische Belastung gehört dazu. Keine einmalige Alibi-Liste.",
            "Neue Software mit Leistungskontrolle → GBU psychisch + Mitbestimmung.",
            "Falle: GBU nur für Maschinen, nie für Softwarearbeit.",
            null, "§ 5 ArbSchG"),
        "t3-top" => F(t, "TOP-Prinzip: Technische vor Organisatorischen vor Persönlichen Maßnahmen. PSA ist letzte, nicht erste Wahl.",
            "Substitution, Kapselung, dann Ablauf, dann Helm/Brille/Handschuhe.",
            "Lärm: Maschine dämmen, bevor Gehörschutz allein ausgegeben wird.",
            "Falle: Nur Warnweste statt technische Trennung vom Staplerverkehr."),
        "t3-asa" => F(t, "Arbeitsschutzausschuss in Betrieben mit mehr als 20 Beschäftigten: AG, BR, Betriebsarzt, Fachkraft für Arbeitssicherheit, Sicherheitsbeauftragte; tagt mindestens vierteljährlich.",
            "Koordinationsgremium, ersetzt nicht die Verantwortung des AG.",
            "Quartalssitzung zu Unfällen und Homeoffice-Ergonomie.",
            "Falle: ASA nur in Großkonzernen ab 500 MA.",
            null, "§ 11 ASiG"),
        "t3-sib" => F(t, "Sicherheitsbeauftragte unterstützen den Unfallversicherungsschutz im Betrieb, ab bestimmten Schwellen, ohne Weisungsrecht wie Vorgesetzte; sie dürfen nicht benachteiligt werden.",
            "Ergänzen Sifa und Betriebsarzt, ersetzen sie nicht.",
            "Erfahrene Fachkraft als SiBe im 30-Personen-Betrieb.",
            "Falle: SiBe = Fachkraft für Arbeitssicherheit (Sifa)."),
        "t3-ergonomie" => F(t, "Ergonomie passt Arbeit an den Menschen: Haltung, Bildschirm, Pausen, Software-Usability, psychische Belastung.",
            "ASR, DIN, Barrierefreiheit überschneiden sich mit UX.",
            "Höhenverstellbarer Tisch, 50-cm-Sehabstand, Unterbrechung von Dauerklikkarbeit.",
            "Falle: Ergonomie nur 'teurer Stuhl'."),
        "t3-brandschutz" => F(t, "Brandschutz: Vorbeugung, Erkennung, Evakuierung, Löschen. Flucht- und Rettungspläne, Unterweisung, Feuerlöscher, Brandschutzhelfer.",
            "Kennzeichnung nach ASR A1.3. Keine versperrten Fluchtwege.",
            "Jährliche Evakuierungsübung, Löscher geprüft.",
            "Falle: Fluchtweg als Lagerfläche."),
        "t3-schilder" => F(t, "Sicherheitszeichen: Gebot (blau rund), Verbot (rot rund mit Querbalken), Warnung (gelb dreieckig), Rettung (grün), Brandschutz (rot). Farbe+Form, nicht Farbe allein in der Prüfung nennen.",
            "ISO 7010 / ASR A1.3. Ergänzende Textzusätze.",
            "Grünes Rettungszeichen Notausgang, blaues Gebot Augenschutz.",
            "Falle: Alle Schilder rot oder nur Farbbedeutung ohne Form."),
        "t3-agg" => F(t, "Das AGG schützt vor Diskriminierung in Beschäftigung und Teilen des Zivilrechts wegen der genannten Merkmale.",
            "Rechtfertigungen eng. Maßnahmen: Beschwerdestelle, Entschädigung, Beweislastmodifikation.",
            "Stelle 'nur Männer unter 30, deutsch' ist unzulässig (sofern keine echte berufliche Anforderung).",
            "Falle: AGG gelte nur für den öffentlichen Dienst.",
            null, "AGG"),
        "t3-agg-merkmale" => F(t, "Geschützte Merkmale: Rasse (Gesetzeswortlaut; in der Lehre rassifizierende Zuschreibung), ethnische Herkunft, Geschlecht, Religion/Weltanschauung, Behinderung, Alter, sexuelle Identität.",
            "Kein allgemeines 'Gerechtigkeitsgesetz' für alle Ungleichheiten (z. B. Wohnort allein nicht).",
            "Ablehnung 'zu alt für Azubi-Stelle' ohne sachlichen Grund.",
            "Falle: Familienstand oder Gewerkschaft als AGG-Merkmal erfinden – andere Schutzrechte können greifen, aber nicht die AGG-Liste verfälschen."),
        "t3-diskriminierung" => F(t, "Unmittelbar: an das Merkmal anknüpfend. Mittelbar: neutrale Regel benachteiligt eine Gruppe wesentlich, ohne gerechtfertigt zu sein. Belästigung und Anweisung zur Diskriminierung sind erfasst.",
            "Positive Maßnahmen können erlaubt sein. Stellenschaltung und Auswahlverfahren dokumentieren.",
            "Vollzeit-Nachtpflicht kann Frauen mit Care-Arbeit mittelbar treffen – Rechtfertigung prüfen.",
            "Falle: Nur direkte Beleidigungen zählen, mittelbare Regeln nie."),
        "t3-mutterschutz" => F(t, "Mutterschutz: Beschäftigungsverbote, Kündigungsverbot, Schutzfristen. Nach der Entbindung grundsätzlich 8 Wochen, bei Früh- und Mehrlingen grundsätzlich 12 Wochen (§ 3 Abs. 2 MuSchG) – nicht 14 Wochen nach der Geburt.",
            "Vor der Entbindung in der Regel 6 Wochen, verzichtbar unter Bedingungen. 6+8=14 insgesamt ist eine häufige Verwechslung mit der reinen Nachschutzfrist. Bei Geburt eines Kindes mit Behinderung Verlängerung der Nachschutzfrist auf 12 Wochen.",
            "Regelgeburt: 8 Wochen nach der Geburt Schutzfrist. Zwillinge: 12 Wochen danach.",
            "Falle: 'Nach der Geburt immer 14 Wochen Mutterschutz.'",
            null, "§ 3 MuSchG", false, null, null, V, VerificationStatus.CorrectedFromSource, "MuSchG", "Mutterschutzfristen"),
        "t3-elternzeit" => F(t, "Elternzeit: unbezahlte Freistellung zur Betreuung, Anspruch nach BEEG, Anmeldung fristgebunden, Kündigungsschutz, Anteil aufteilbar zwischen Eltern, Teilzeit möglich unter Voraussetzungen.",
            "Maximal 3 Jahre pro Elternteil grundsätzlich, mit Übertragungsoptionen in einen späteren Zeitraum – aktuelle BEEG-Fassung prüfen.",
            "Anmeldung 7 Wochen vor Beginn (bzw. 13 in späteren Zeiträumen nach aktueller Rechtslage – in der Prüfung Gesetzestext/Aufgabenangabe).",
            "Falle: Elternzeit = Elterngeld (Geldleistung vs. Freistellung)."),
        "t3-elterngeld" => F(t, "Elterngeld ist eine einkommensabhängige Leistung des BEEG (Basis, Plus, Partnerschaftsbonus), kein automatisches Gehalt vom AG.",
            "Antragsbehörde, Höchst-/Mindestbeträge zeitabhängig – Zahlen nur mit Gültigkeit nennen. Elterngeld ≠ Elternzeit.",
            "12 Monatsbeträge Basiselterngeld plus Partnermonate nach den aktuellen Regeln.",
            "Falle: Elterngeld als AG-Pflichtgehalt zu 100 % netto."),
        "t3-wirtschaft" => F(t, "VWL-Grundlagen: Sektoren, Markt, Preisbildung, Marktformen, staatliche Rahmen der sozialen Marktwirtschaft, Stabilitätspolitik.",
            "Mikro (Haushalt, Unternehmen, Markt) vs. Makro (Inflation, Arbeitslosigkeit, Wachstum).",
            "Softwaremarkt mit wenigen großen Anbietern tendiert zu Oligopol.",
            "Falle: Preis immer 'der Staat setzt ihn fest' in der sozialen Marktwirtschaft."),
        "t3-sektoren" => F(t, "Primär: Urproduktion, sekundär: Industrie/Verarbeitung, tertiär: Dienstleistungen. Quartär manchmal Information/Wissen.",
            "FIAE ist tertiär/quartär. Strukturwandel: Tertiarisierung.",
            "Landwirtschaft → Fabrik → Cloud-Dienstleister.",
            "Falle: IT als 'primär', weil 'am Computer produziert'."),
        "t3-soziale-marktwirtschaft" => F(t, "Soziale Marktwirtschaft: Wettbewerb und Privateigentum mit sozialem Ausgleich und Ordnungsrahmen (Kartellrecht, Sozialversicherung, Tarifautonomie).",
            "Weder Laissez-faire noch Zentralverwaltung. Leitbild der BRD.",
            "GWB gegen Kartelle, SV gegen Lebensrisiken, TVG für Löhne.",
            "Falle: Soziale Marktwirtschaft = Planwirtschaft mit etwas Freiheit."),
        "t3-marktversagen" => F(t, "Marktversagen: öffentliche Güter, Externalitäten, natürliche Monopole, Informationsasymmetrie, ruinöse Konkurrenz – Rechtfertigung für Staatseingriffe, nicht für jeden Eingriff.",
            "Beispiel: Umweltschäden, Impfungen, Netzwerke.",
            "CO2-Ausstoß als negative Externalität, CO2-Preis als Internalisierung.",
            "Falle: Jeder unbequeme Preis sei Marktversagen."),
        "t3-marktformen" => F(t, "Polypol viele Anbieter/Nachfrager, Oligopol wenige Anbieter, Monopol einer, Monopson ein Nachfrager. Vollkommener Markt ist Modell.",
            "Preissetzungsspielräume steigen zum Monopol. Kartellrecht begrenzt Absprachen.",
            "Lokaler einziger ISP: Angebotsmonopol-Tendenz.",
            "Falle: Oligopol immer illegal – die Form allein ist kein Kartell."),
        "t3-angebot-nachfrage" => F(t, "Angebot steigt typisch mit dem Preis, Nachfrage sinkt (ceteris paribus). Schnittpunkt: Gleichgewicht.",
            "Verschiebung der Kurven vs. Bewegung auf der Kurve. Determinanten: Einkommen, Präferenzen, Kosten, Technologie.",
            "Höhere Entwicklergehälter verschieben Software-Angebot nach oben/links (teurer).",
            "Falle: Nachfrage sinkt, weil der Preis sank – das wäre Bewegung auf der Kurve, nicht automatisch Verschiebung."),
        "t3-gleichgewichtspreis" => F(t, "Gleichgewichtspreis räumt den Markt: angebotene = nachgefragte Menge. Darüber Angebotsüberhang, darunter Nachfrageüberhang.",
            "Preismechanismus koordiniert. Staatliche Höchst-/Mindestpreise erzeugen Knappheit oder Überschuss, wenn bindend.",
            "Ticketpreis 80 €, Menge 500 = Gleichgewicht laut Aufgabe.",
            "Falle: Gleichgewicht als 'gerechter Preis' moralisch, nicht analytisch."),
        "t3-ueberschuss" => F(t, "Angebotsüberhang: Preis über Gleichgewicht, unverkaufte Menge. Nachfrageüberhang: Preis darunter, Warteschlangen/Knappheit.",
            "Anpassung: Preis sinkt bzw. steigt, wenn frei. Rationierung bei Höchstpreisen.",
            "Mindestpreis über GG → Butterberg/Softwarelizenzen unverkäuflich.",
            "Falle: Überhang-Begriffe zu vertauschen."),
        "t3-kartellverbot" => F(t, "§ 1 GWB / Art. 101 AEUV: Vereinbarungen und abgestimmte Verhaltensweisen, die den Wettbewerb beschränken, sind grundsätzlich verboten. Es gibt kein aktuelles Universalprinzip 'Normen- und Typenkartelle sind anmeldepflichtig und deshalb grundsätzlich erlaubt'.",
            "Freistellung nach § 2 GWB analog Art. 101 Abs. 3 (Effizienz, Verbraucheranteil, Unerlässlichkeit, keine Ausschaltung des Wettbewerbs) oder gesetzliche Bereichsausnahmen. Schwere Kernbeschränkungen (Preis, Marktaufteilung) fast nie frei. Historische Anmeldesysteme alter GWB-Fassungen sind historisch zu kennzeichnen.",
            "Zwei Helpdesk-Anbieter sprechen Endkundenpreise ab → verboten.",
            "Falle: 'Normen- und Typenkartell anmelden = erlaubt' als aktuelle Regel.",
            null, "§§ 1, 2 GWB, Art. 101 AEUV", false, null, null, V, VerificationStatus.CorrectedFromSource, "GWB aktuell", "Kartellverbot"),
        "t3-gwb-ausnahmen" => F(t, "Mögliche Freistellungen folgen legal exception: Vorteile, Verbraucherpartizipation, Unerlässlichkeit, Restwettbewerb. Bagatellbekanntmachungen und Leitlinien helfen, ersetzen aber nicht die Prüfung. Fusionskontrolle ist ein anderes Instrument.",
            "Mittelstandskooperationen können unter engen Bedingungen zulässig sein. Selbsteinschätzung der Unternehmen, Bußgeldrisiko.",
            "Technische Normungsarbeit mit offenen, transparenten Verfahren vs. Preisabsprache getarnt als 'Norm'.",
            "Falle: Jede Kooperation von Wettbewerbern sei nach Anmeldung zulässig.",
            null, "§ 2 GWB"),
        "t3-unternehmen" => F(t, "Rechtsformen unterscheiden Haftung, Geschäftsführung, Kapital, Publizität, Steuer und Register (HRA/HRB).",
            "Personen- vs. Kapitalgesellschaften. Formkaufleute. UG als GmbH-Variante.",
            "Zwei Freelancer: GbR vs. GmbH wegen Haftung.",
            "Falle: GmbH-Gesellschafter haften immer persönlich wie OHG-Gesellschafter."),
        "t3-einzelunternehmen" => F(t, "Einzelunternehmen: eine natürliche Person, unbeschränkt persönlich haftend, ggf. e.K. im HRA, kein Mindestkapital.",
            "Einfach, Risiko privat. Kaufmannseigenschaft nach HGB-Kriterien.",
            "Selbstständige Entwicklerin ohne Gesellschaftsvertrag.",
            "Falle: Einzelunternehmen = immer Kleingewerbe ohne HGB."),
        "t3-gbr" => F(t, "GbR: Personengesellschaft, grundsätzlich gesamtschuldnerische Haftung der Gesellschafter, kein gesetzliches Mindestkapital, seit Modernisierung ggf. eGbR im Gesellschaftsregister.",
            "Innen- vs. Außengesellschaft. Geschäftsführung gemeinschaftlich, soweit nicht anders.",
            "Drei Studierende entwickeln eine App als GbR.",
            "Falle: GbR-Gesellschafter haften nur mit Einlage wie GmbH."),
        "t3-ohg" => F(t, "OHG: Personengesellschaft, Betrieb eines Handelsgewerbes, alle Gesellschafter unbeschränkt, HRA, keine gesetzliche Mindesteinlage.",
            "Geschäftsführung einzelvertretend im Zweifel. Kaufmann.",
            "Zwei Kaufleute führen Softwarehaus als OHG.",
            "Falle: OHG braucht 25.000 € Stammkapital."),
        "t3-kg" => F(t, "KG: Komplementäre haften unbeschränkt (führen), Kommanditisten beschränkt auf Einlage, HRA.",
            "Kommanditist grundsätzlich keine Geschäftsführung. GmbH & Co. KG als Sonderform.",
            "Kapitalgeber als Kommanditist, Gründer als Komplementär.",
            "Falle: Kommanditist hafte wie Komplementär nach Eintragung der Einlage immer voll – nach Eintragung beschränkt, vorher ggf. anders."),
        "t3-gmbh" => F(t, "GmbH: Kapitalgesellschaft, Haftung grundsätzlich Gesellschaftsvermögen, Stammkapital mind. 25.000 €, Geschäftsführer, HRB, notarieller Vertrag.",
            "Gesellschafterversammlung. Mantel- und Wirtschaftsstrafrecht bei Unterkapitalisierung/Insolvenzverschleppung gesondert.",
            "Helpdesk GmbH mit 25.000 €, GF angestellt.",
            "Falle: GmbH ohne Stammkapital wie UG ohne Hinweis auf UG-Sonderregeln."),
        "t3-ug" => F(t, "UG (haftungsbeschränkt): Mindeststammkapital ab 1 €, Thesaurierungspflicht (Rücklage 25 % des Jahresüberschusses) bis 25.000 € erreicht und Umbenennung möglich, HRB, Haftung wie GmbH grundsätzlich auf Gesellschaftsvermögen.",
            "Kein 'GmbH light ohne Pflichten'. Gläubigerschutz über Rücklage und Bezeichnung.",
            "Start-UG mit 300 € Stammkapital, 25 % in gesetzliche Rücklage.",
            "Falle: UG ohne Rücklagepflicht und mit 25.000 € Verwechslung."),
        "t3-ag" => F(t, "AG: Kapitalgesellschaft, Grundkapital mind. 50.000 €, Vorstand, Aufsichtsrat, Hauptversammlung, HRB, Aktie als Anteil.",
            "Strenge Organisation, Kapitalmarkt möglich. Kleine AG erleichtert, ersetzt aber nicht die Organe.",
            "Software-AG mit 50.000 €, Vorstand führt.",
            "Falle: AG-Mindestkapital 25.000 € (das ist GmbH)."),
        "t3-eg" => F(t, "eG: Förderzweck der Mitglieder, Vorstand und Aufsichtsrat, Mindestmitglieder, Eintragung Genossenschaftsregister, Prüfungspflicht.",
            "Identität Prinzip: Mitglieder = Nutzer. Nachschusspflicht je Satzung.",
            "Energie- oder IT-Einkaufsgenossenschaft.",
            "Falle: eG = Verein ohne wirtschaftliches Unternehmen."),
        "t3-personen-kapital" => F(t, "Personengesellschaften: persönliche Haftung mindestens einer Person, Selbstorganschaft, HRA typisch. Kapitalgesellschaften: Trennungsprinzip, Drittorganschaft möglich, HRB, Mindestkapital.",
            "GbR/OHG/KG vs. GmbH/UG/AG. Steuerlich Mitunternehmerschaft vs. Körperschaft.",
            "OHG persönlich, GmbH getrennt.",
            "Falle: KG als Kapitalgesellschaft einordnen, nur weil Kommanditisten beschränkt haften."),
        "t3-haftung" => F(t, "Haftung: unbeschränkt persönlich (EU, OHG, Komplementär, GbR) vs. beschränkt auf Gesellschaftsvermögen (GmbH, UG, AG) plus Durchgriff in Missbrauchsfällen.",
            "Gesamtschuldnerisch bei mehreren persönlich Haftenden. Einlage ausstehend → Differenzhaftung.",
            "GmbH-Insolvenz: Gläubiger grundsätzlich nicht an das Privathaus, außer Garantie/Durchgriff.",
            "Falle: 'GmbH-GF haftet nie privat' – Organhaftung, Steuern, Sozialversicherung können treffen."),
        "t3-geschaeftsfuehrung" => F(t, "Geschäftsführung: Innenverhältnis wer handelt darf; Vertretung: Außenverhältnis. GmbH: GF, OHG: Gesellschafter, AG: Vorstand.",
            "Gesamt- vs. Einzelvertretung. Prokura HGB. Missbrauch der Vertretungsmacht.",
            "GF schließt Lizenzvertrag im Namen der GmbH.",
            "Falle: Gesellschafter einer GmbH ohne GF-Bestellung vertritt immer."),
        "t3-mindestkapital" => F(t, "Mindestkapital: GmbH 25.000 €, AG 50.000 €, UG 1 € plus Rücklage, OHG/GbR/EU keines gesetzlich.",
            "Sacheinlagen bewertbar. Kein 'Parken' ohne Volleinzahlung bei GmbH ohne Regelung – mind. Hälfte bei Anmeldung GmbH (12.500) kennen.",
            "GmbH-Gründung 25.000, davon 12.500 vor Anmeldung einzuzahlen (bar).",
            "Falle: AG 25.000, GmbH 50.000 – vertauscht."),
        "t3-gewinn" => F(t, "Gewinnverteilung: GmbH nach Geschäftsanteilen, OHG nach HGB erst 4 % Kapitalanteil dann Köpfe soweit nicht anders, KG Kommanditisten nach Einlage, GbR nach Köpfen gesetzlich, TV/Gesellschaftsvertrag geht vor.",
            "Immer zuerst den Vertrag lesen. Verlustverteilung analog, KG: Kommanditist bis Einlage.",
            "GmbH zwei Gesellschafter 60/40 → Gewinn 60/40.",
            "Falle: Immer zu gleichen Teilen unabhängig von Anteilen/Vertrag."),
        "t3-hra-hrb" => F(t, "HRA: Kaufleute und Personengesellschaften (e.K., OHG, KG). HRB: Kapitalgesellschaften (GmbH, UG, AG). Publizität des Registers.",
            "Nummer, Sitz, Vertretung. Einsicht öffentlich. Positive und negative Publizität §§ 15 HGB.",
            "GmbH → HRB 12345, OHG → HRA 678.",
            "Falle: GmbH im HRA, OHG im HRB."),
        "t3-publizitaet" => F(t, "Registerpublizität: gutgläubiger Verkehr darf auf Eintragungen vertrauen (unter den Regeln des § 15 HGB), nicht eingetragene/bekannte Tatsachen können unschädlich sein oder nicht.",
            "Unterscheide: nicht eingetragen und nicht bekannt vs. eingetragen aber falsch. Publizität ≠ Werbung.",
            "Prokura im HRA eingetragen, Dritte dürfen darauf vertrauen.",
            "Falle: Alles, was nicht im Register steht, existiert rechtlich nicht (z. B. GbR ohne Eintragung kann trotzdem bestehen)."),
        "t3-organisation" => F(t, "Aufbauorganisation verteilt Aufgaben, Kompetenzen, Verantwortung; Ablauforganisation zeitlich-logische Prozesse.",
            "Stellen, Instanzen, Leitungsspanne, Stäbe.",
            "Helpdesk: 1st-Level-Stelle, Instanz Teamleitung.",
            "Falle: Organigramm = Prozessmodell."),
        "t3-liniensysteme" => F(t, "Einliniensystem: eine Weisungslinie, klar, langsam. Mehrlinie: mehrere Vorgesetzte, Fach- vs. Disziplinar. Stablinie: Linie plus beratende Stäbe ohne Weisung. Matrix: mindestens zwei Dimensionen (Produkt/Funktion), Konfliktpotenzial.",
            "Vor- und Nachteile in der Prüfung gegenüberstellen.",
            "Matrix: Projektleiter und Fachvorgesetzter IT.",
            "Falle: Stab hat Weisungsrecht wie Linie."),
        "t3-projektorganisation" => F(t, "Projektorganisation: Stabsprojekt (Einfluss-Projektmanagement), Matrixprojekt, reine Projektorganisation (Taskforce) – Autonomie vs. Ressourceneinsatz.",
            "Magisches Dreieck bleibt. Lenkungsausschuss.",
            "Reines Projekt: Team 100 % abgestellt bis Go-Live.",
            "Falle: Jedes Projekt sei eine eigene GmbH."),
        "t3-maslow" => F(t, "Maslow: Bedürfnishierarchie von physiologisch über Sicherheit, Soziales, Wertschätzung zu Selbstverwirklichung. Nicht streng empirisch, aber Prüfungsstoff Motivation.",
            "Untere Stufen 'zuerst', Kritik: Kultur, Sprünge. Nicht mit Herzberg gleichsetzen ohne Unterschied.",
            "Existenzsicherung vor Statussymbol-Firmenwagen als Motivator-These.",
            "Falle: Maslow beweise, dass IT-Leute nur Selbstverwirklichung wollen."),
        "t3-entgelt" => F(t, "Entgeltformen steuern Leistung und Einkommen: Zeitlohn, Akkord, Prämie, Provision, Mischformen. Mindestlohn als Untergrenze.",
            "Gerechtigkeit, Messbarkeit, Qualitätsrisiko beim Akkord.",
            "Support: Zeitlohn plus Qualitätsprämie, nicht reiner Stückakkord an Tickets ohne Qualitätsmaß.",
            "Falle: Akkord immer unzulässig."),
        "t3-zeitlohn" => F(t, "Zeitlohn vergütet Anwesenheit/Arbeitszeit unabhängig vom Stückergebnis. Planbar, wenig Leistungsanreiz, Qualität oft höher.",
            "Überstunden, Zuschläge, Arbeitszeitkonto. Typisch in IT-Gehältern.",
            "35 €/h bzw. Monatsgehalt.",
            "Falle: Zeitlohn = kein Weisungsrecht des AG."),
        "t3-akkord" => F(t, "Akkordlohn knüpft am Mengenergebnis an (Stück- oder Zeitakkord). Vorgegebene Normalleistung, Risiko von Qualitätseinbußen und Überlastung, Mitbestimmung/Arbeitsschutz.",
            "Ungeeignet, wo Qualität/Sicherheit nicht zählbar ist. Mindestlohn bleibt Untergrenze.",
            "Stückakkord Montage; in der Softwareentwicklung untypisch 'LOC-Akkord'.",
            "Falle: Akkord ohne Zeitstudie/Vorgabe als fair messbar."),
        "t3-praemie" => F(t, "Prämienlohn kombiniert Grundentgelt mit Zulage für messbare Extra-Ziele (Qualität, Ersparnis, Anwesenheit).",
            "Ziele SMART und beeinflussbar. Keine reinen Zufallsziele.",
            "Prämie für Kundenzufriedenheit > 90 % und Fehlerquote < 2 %.",
            "Falle: Prämie, die nur das Einhalten gesetzlicher Pflichten belohnt, als einziges QS-System."),
        "t3-provision" => F(t, "Provision: Anteil am vermittelten Geschäft, typisch Vertrieb. Kombiniert oft mit Fixum. Nachvertragliche Provision und Stornohaftung vertraglich.",
            "Transparenz der Bemessungsgrundlage. Mindestlohn/Fixum beachten.",
            "8 % vom Lizenzumsatz plus Grundgehalt.",
            "Falle: 100 % Provision ohne Fixum bei Abhängigkeit, ohne rechtliche Grenzen zu prüfen."),
        "t3-mindestlohn" => F(t, "Der gesetzliche Mindestlohn beträgt seit 1.1.2026 13,90 € brutto je Zeitstunde, ab 1.1.2027 14,60 € (MiLoG, Anpassungsverordnung).",
            "Gilt grundsätzlich für Arbeitnehmerinnen und Arbeitnehmer; Ausnahmen eng (z. B. bestimmte Praktika, Jugendliche ohne abgeschlossene Ausbildung unter Bedingungen). Kontrolle Zoll. Branchenmindestlöhne können höher sein.",
            "20-Stunden-Woche * 13,90 € = 278 € brutto/Woche ohne Zuschläge.",
            "Falle: 12,82 € (2025) oder 12,41 € als aktuellen allgemeinen Mindestlohn zu lehren.",
            null, "MiLoG, 5. Mindestlohnanpassungsverordnung", true, new DateOnly(2026, 1, 1), new DateOnly(2026, 12, 31), V, VerificationStatus.Verified, "BMAS", "Mindestlohn 2026"),
        "t3-kaufvertrag" => F(t, "Kaufvertrag § 433 BGB: Verkäufer übergibt und verschafft Eigentum, Käufer zahlt den Preis und nimmt ab. Zustandekommen durch zwei übereinstimmende Willenserklärungen.",
            "Stück- vs. Gattungskauf, Verbrauchsgüterkauf Sonderregeln. Erfüllungsort, Gefahrübergang.",
            "Softwarelizenzkauf vs. Werkvertrag zur Individualentwicklung unterscheiden.",
            "Falle: Jede IT-Leistung sei immer Kauf, nie Dienst/Werk."),
        "t3-antrag-annahme" => F(t, "Antrag (Angebot) und Annahme müssen sich decken. Bindung, Widerruf, verspätete/abändernde Annahme = neuer Antrag. Invitiato ad offerendum (Schaufenster, Webshop-Anzeige oft).",
            "Zugang erforderlich. Schweigen im Handelsverkehr nur ausnahmsweise.",
            "Angebot 2.000 €, 'ja, aber 1.800 €' = neues Angebot.",
            "Falle: Jede Website-Preisauszeichnung sei bereits bindender Antrag ohne AGB-Prüfung."),
        "t3-geschaeftsfaehigkeit" => F(t, "Geschäftsunfähig <7, beschränkt 7–17, voll ab 18. Taschengeldparagraph, rechtlicher Vorteil, Einwilligung/Genehmigung gesetzlicher Vertreter.",
            "Ausbildungsvertrag: Minderjährige brauchen Zustimmung. Digitaler Click ist WE.",
            "16-Jähriger kauft Smartphone teuer ohne Zustimmung → schwebend unwirksam, außer Taschengeld reicht nachweisbar.",
            "Falle: 16-Jährige seien voll geschäftsfähig, weil berufstätig."),
        "t3-sachmangel" => F(t, "Sachmangel: Ist-Beschaffenheit weicht von vereinbarter (sonst üblicher/gewöhnlicher Verwendung, Werbung, Montage) ab. Nacherfüllung, Rücktritt, Minderung, Schadensersatz nach §§ 437 ff., Fristen, Verbraucherrecht.",
            "Software: vereinbarte Version/Funktion. Update-Pflichten im Verbrauchsgüterkauf (Waren mit digitalen Elementen) aktuell halten.",
            "Helpdesk ohne die zugesicherte CSV-Exportfunktion.",
            "Falle: Jeder Wunsch ohne Vereinbarung sei Mangel."),
        "t3-verzug" => F(t, "Lieferverzug: Schuldner leistet nicht rechtzeitig trotz Fälligkeit und Mahnung (oder Entbehrlichkeit). Zahlungsverzug analog. Annahmeverzug: Gläubiger nimmt nicht an.",
            "Mahnung, Ablehnungsandrohung, Schadensersatz statt der Leistung. Verbraucherdarlehen/sonstige Sondervorschriften nicht mischen.",
            "Liefertermin 1.3. überschritten, Mahnung 5.3. → Verzug.",
            "Falle: Verzug immer ohne Mahnung, auch wenn nicht kalendermäßig bestimmt und nicht entbehrlich."),
        "t3-maengelarten" => F(t, "Offene Mängel bei üblicher Untersuchung erkennbar, versteckte nicht, arglistig verschwiegene vom Verkäufer bewusst verheimlicht – Verjährung und Rügepflicht greifen unterschiedlich.",
            "Arglist hemmt/verlängert erheblich. Verbraucher vs. Unternehmer.",
            "Haarriss im Gehäuse versteckt; manipulierte Laufleistung arglistig.",
            "Falle: Versteckte Mängel sofort mit offenen gleich rügen müssen, obwohl nicht erkennbar."),
        "t3-ruesselpflicht" => F(t, "Kaufleute: Untersuchungs- und Rügeobliegenheit § 377 HGB unverzüglich nach Ablieferung, sonst Genehmigung, außer arglistig. Gilt nicht für Verbraucher.",
            "Rügeinhalt: Mangel beschreiben. Unverzüglich = ohne schuldhaftes Zögern.",
            "Händler prüft Lieferung am nächsten Werktag, rügt fehlende Lizenzen.",
            "Falle: § 377 HGB auf Privatkauf im Internet anwenden.",
            null, "§ 377 HGB"),
        "t3-verjaehrung" => F(t, "Kaufrechtliche Mängelansprüche verjähren regelmäßig in 2 Jahren ab Ablieferung (§ 438 Abs. 1 Nr. 3 BGB), Bau 5 Jahre, arglistig 3 Jahre ab Kenntnis nach Regelverjährung; AGB-Verkürzungen gegenüber Verbrauchern begrenzt.",
            "Hemmung, Neubeginn. HGB-Rüge ist keine Verjährung, sondern Obliegenheit.",
            "Laptop an Verbraucher: 2 Jahre, Beweislastumkehrfrist im Verbrauchsgüterkauf aktuell (1 Jahr) nicht mit Verjährung verwechseln.",
            "Falle: Immer 4 Wochen Verjährung analog HGB-Rüge."),
        "t3-mahnung" => F(t, "Mahnung setzt den Schuldner in Verzug, wenn Leistung fällig und durchsetzbar ist, außer die Mahnung ist entbehrlich (Kalender, Ernsthafte Verweigerung, Fristsetzung im Antrag …).",
            "Rechnung allein ist nicht immer Mahnung. Verzugszinsen, Pauschale § 288 BGB im Geschäftsverkehr.",
            "Zweite Mail 'Hiermit mahne ich die Zahlung der Rechnung 4711 an'.",
            "Falle: Drei Mahnungen seien gesetzlich Pflicht vor Verzug."),
        "t3-mahnbescheid" => F(t, "Gerichtliches Mahnverfahren: Antrag Mahnbescheid, Widerspruch 2 Wochen, sonst Vollstreckungsbescheid. Günstig für unstreitige Geldforderungen.",
            "Falsches Gericht, unbestimmte Forderung → Probleme. Nach Widerspruch streitiges Verfahren.",
            "Unbezahlte 2.400 € Rechnung, kein Widerspruch, dann VB.",
            "Falle: Mahnbescheid = bereits Pfändung ohne weiteren Titel."),
        "t3-vollstreckung" => F(t, "Vollstreckungsbescheid ist ein Vollstreckungstitel, wenn kein Einspruch. Zwangsvollstreckung durch GV, Konto-/Lohnpfändung mit Freibeträgen.",
            "Einspruch gegen VB binnen 2 Wochen. Titel, Klausel, Zustellung.",
            "VB rechtskräftig → Pfändung.",
            "Falle: VB ohne vorheriges Verfahren aus heiterem Himmel bei bestrittenen Mängeln ohne Mahnantrag."),
        "t3-gerichtsstaendigkeit" => F(t, "Sachliche und örtliche Zuständigkeit: Zivil (AG/LG nach Streitwert und Materie), Arbeit, Sozial, Finanz, Verwaltung. Sonderzuständigkeiten (Miete, Familiensachen) beachten.",
            "Instanzenzüge nicht mischen. 2026: allgemeine AG-Zivilgrenze 10.000 €.",
            "Kündigungsschutz → Arbeitsgericht, nicht AG-Zivil.",
            "Falle: Jede Streitigkeit zum Amtsgericht unabhängig vom Rechtsweg."),
        "t3-amtsgericht" => F(t, "Das Amtsgericht ist in Zivilsachen grundsätzlich bis 10.000 € Streitwert zuständig (seit 1.1.2026, zuvor 5.000 €), vorbehaltlich besonderer Zuständigkeiten (z. B. Wohnraummietsachen unabhängig vom Wert).",
            "Landgericht ab über 10.000 € in allgemeinen Zivilsachen. Anwaltszwang am LG, nicht am AG. Historische 5.000-€-Aufgaben als historisch markieren.",
            "8.000 € Kaufpreisklage 2026 → AG, 12.000 € → LG, Miete Wohnung auch bei 15.000 € oft AG.",
            "Falle: 5.000 € als aktuelle universelle Grenze.",
            null, "GVG i. d. F. ab 1.1.2026", true, new DateOnly(2026, 1, 1), null, V, VerificationStatus.CorrectedFromSource, "GVG", "AG-Streitwert 10.000 €"),
        "t3-landgericht" => F(t, "Landgericht: erste Instanz über der AG-Wertgrenze in allgemeinen Zivilsachen, außerdem bestimmte Materien, Berufung vom AG. Kammern, Anwaltszwang.",
            "Kartell-, Kapital-, Bausachen können spezialisiert sein.",
            "12.500 € Werklohnstreit zwischen Unternehmern → LG.",
            "Falle: LG für alle Arbeitsstreitigkeiten (das ist ArbG)."),
        "t3-arbeitsgericht" => F(t, "Arbeitsgerichte für Rechtsstreitigkeiten aus dem Arbeitsverhältnis, BetrVG, TV u. a., unabhängig vom Streitwert. Güteverhandlung zuerst. In der ersten Instanz oft ohne Anwaltszwang.",
            "Kündigungsschutzklage Frist 3 Wochen. Urteils- vs. Beschlussverfahren.",
            "Kündigung angreifen: ArbG, nicht Zivil-AG.",
            "Falle: 9.000 € Lohnklage 2026 zum Amtsgericht, weil unter 10.000 €."),
        "t3-sozialgericht" => F(t, "Sozialgerichte: Streitigkeiten der Sozialversicherung, Grundsicherung, Schwerbehindertenrecht u. a., gerichtskostenfrei in vielen Verfahren für Versicherte.",
            "Widerspruchsverfahren vorher typisch. Drei Instanzen SG/LSG/BSG.",
            "Ablehnung einer BK durch die BG → SG.",
            "Falle: Rentenablehnung Finanzgericht."),
        "t3-finanzgericht" => F(t, "Finanzgerichte: Steuer- und Zollsachen gegen Finanzbehörden. Klage nach Einspruch. FG erste Tatsacheninstanz, Revision BFH.",
            "Keine allgemeinen Verbraucherstreitigkeiten über den Preis im Laden.",
            "Einspruch gegen Einkommensteuerbescheid erfolglos → FG.",
            "Falle: USt-Streit Amtsgericht."),
        "t3-verwaltungsgericht" => F(t, "Verwaltungsgerichte: öffentlich-rechtliche Streitigkeiten nichtverfassungsrechtlicher Art, soweit nicht andere Gerichte (z. B. Baugenehmigung, Gewerbeuntersagung, Hochschule).",
            "Widerspruch oft vorgeschaltet. VwGO. Nicht für private Kaufverträge.",
            "Ablehnung einer Aufenthalts- oder Gewerbeerlaubnis.",
            "Falle: Abmahnung im Job zum VG statt ArbG."),
        "t3-steuern" => F(t, "Steuern sind Zwangsabgaben ohne individuelle Gegenleistung. Lohnsteuer ist Erhebungsform der ESt, KSt auf Körperschaften, GewSt auf Ertrag von Gewerbebetrieben, USt auf Umsätze, SolZ Zuschlag.",
            "AG als Einbehaltender der LSt/SV. Vorsteuerabzug bei Unternehmern.",
            "GmbH: KSt + GewSt + SolZ auf KSt, USt auf Rechnungen.",
            "Falle: Lohnsteuer und Einkommensteuer als zwei völlig getrennte Steuerarten ohne Zusammenhang."),
        "t3-lohnsteuer" => F(t, "Lohnsteuer ist eine Erhebungsform der Einkommensteuer auf Einkünfte aus nichtselbständiger Arbeit, vom AG einbehalten und abgeführt, abhängig von Steuerklasse und Faktoren.",
            "Jahresausgleich über Veranlagung möglich. ELStAM. Kein eigenes 'Steuerstrafrecht nur LSt' ohne ESt.",
            "Gehaltsabrechnung: Brutto − SV − LSt − SolZ − ggf. KiSt = Netto (vereinfacht).",
            "Falle: Azubi zahle keine Lohnsteuer grundsätzlich – hängt vom Einkommen/Freibetrag ab."),
        "t3-est" => F(t, "Einkommensteuer erfasst sieben Einkunftsarten, tariflich progressiv mit Grundfreibetrag (jährlich angepasst, zeitbezogen angeben).",
            "Zu versteuern ist das zu versteuernde Einkommen nach Abzügen. Veranlagung, Vorauszahlungen.",
            "Einkünfte aus Gewerbebetrieb eines Einzelunternehmers → ESt, nicht KSt.",
            "Falle: GmbH zahlt ESt statt KSt."),
        "t3-kst" => F(t, "Körperschaftsteuer besteuert das Einkommen von juristischen Personen (GmbH, AG …), Satz gesetzlich (aktuell 15 % plus SolZ – bei Änderung kennzeichnen).",
            "Verdeckte Gewinnausschüttung. Organschaft. Nicht für Personengesellschaften als solche (Transparenzprinzip).",
            "GmbH-Gewinn 100.000 € → KSt 15.000 € plus SolZ, plus GewSt.",
            "Falle: OHG zahlt Körperschaftsteuer."),
        "t3-gewst" => F(t, "Gewerbesteuer: Realsteuer der Gemeinden auf den Gewerbeertrag, Messzahl, Hebesatz. Freibetrag für natürliche Personen/PersG, nicht für Kapitalgesellschaften.",
            "Anrechnung auf ESt begrenzt. Zerlegung auf Gemeinden.",
            "Gemeindehebesatz 400 %, Messbetrag 10.000 € → 40.000 € GewSt grob (ohne Staffel/Freibetrag-Feinheiten der Aufgabe).",
            "Falle: GewSt nur Kapitalgesellschaften oder nur Einzelunternehmen."),
        "t3-ust" => F(t, "Umsatzsteuer besteuert Lieferungen und Leistungen eines Unternehmers im Inland. Regelsteuersatz 19 %, ermäßigt 7 % für Katalog, Steuerbefreiungen, Ist- vs. Sollversteuerung, Kleinunternehmerregelung.",
            "Steuersätze können sich ändern – in Aufgaben den genannten Satz nutzen, aktuell 19/7 als Standard 2026 sofern unverändert.",
            "Rechnung 1.000 € netto + 190 € USt = 1.190 €.",
            "Falle: Privatperson ohne Unternehmereigenschaft führt USt auf eBay-Einzelverkauf immer ab – Klein-/Liebhaberei- und Schwellen prüfen, nicht pauschal."),
        "t3-vorsteuer" => F(t, "Vorsteuer ist die dem Unternehmer in Rechnungen gesondert ausgewiesene USt, die er unter Voraussetzungen vom Finanzamt als Vorsteuerabzug mit der eigenen USt saldieren kann.",
            "Rechnungspflichtangaben. Ausschluss bei steuerfreien Umsätzen ohne Optionsrecht. Kleinunternehmer ohne Ausweis.",
            "Einkauf Server 1.190 € brutto, 190 € Vorsteuer, Verkauf Leistungen mit 19 %.",
            "Falle: Vorsteuer = Lohnsteuer. Oder Privatperson zieht Vorsteuer."),
        "t3-soli" => F(t, "Solidaritätszuschlag ist ein Zuschlag zur ESt/KSt/LSt, nicht zur USt. Für viele ESt-Zahler gilt eine Freigrenze, sodass der SolZ oft nicht anfällt; Körperschaften zahlen ihn auf die KSt.",
            "Prozentsatz 5,5 % der Bemessungsgrundlage, wo er anfällt. Nicht 'abgeschafft für alle'.",
            "GmbH: 5,5 % der KSt. Durchschnittsarbeitnehmer oft 0 wegen Freigrenze.",
            "Falle: SolZ auf die USt oder 'existiert nicht mehr'."),
        "t3-konjunktur" => F(t, "Konjunktur: Schwankungen der gesamtwirtschaftlichen Aktivität (Aufschwung, Boom, Abschwung, Rezession). Stabilisierung durch Geld- und Fiskalpolitik, time lags.",
            "Indikatoren: BIP, Arbeitslosigkeit, Auftragseingang, VPI. Überhitzung vs. Unterauslastung.",
            "Rezession: BIP rückläufig, Arbeitslosigkeit steigt, EZB kann lockern (Zielkonflikt Inflation).",
            "Falle: Jeder Börsenrückgang = Rezession."),
        "t3-inflation" => F(t, "Inflation: anhaltender Anstieg des Preisniveaus, Kaufkraftverlust. Gemessen z. B. am VPI. Ursachen nachfrage-/angebotsseitig.",
            "Geringe Inflation Ziel der EZB (um 2 % mittelfristig). Hyperinflation Extrem.",
            "VPI +3 % in 12 Monaten.",
            "Falle: Ein einzelner Preisanstieg bei Butter = Inflation der Volkswirtschaft."),
        "t3-deflation" => F(t, "Deflation: anhaltender Rückgang des Preisniveaus, Konsumverschiebung in die Zukunft, reale Schuldenlast steigt, Abwärtsspirale möglich.",
            "Selten und gefürchtet. Nicht dasselbe wie Disinflation (sinkende Inflationsrate, Preise steigen langsamer).",
            "Preise −1 % über Monate, Investitionen werden verschoben.",
            "Falle: Disinflation als Deflation zu bezeichnen."),
        "t3-stagflation" => F(t, "Stagflation: Stagnation/Rezession plus Inflation, oft angebotsseitig (Schocks). Klassische Nachfragepolitik Zielkonflikt.",
            "1970er Ölpreisschocks als historisches Beispiel, als historisch markieren.",
            "Produktion sinkt, Preise steigen gleichzeitig.",
            "Falle: Stagflation = nur hohe Arbeitslosigkeit ohne Preisdruck."),
        "t3-vpi" => F(t, "Der Verbraucherpreisindex misst die Preisentwicklung eines Warenkorbs privater Haushalte, Basisjahr, Gewichtung. Inflationsrate = Veränderung des VPI.",
            "HVPI für EZB-Vergleich. Qualitätsbereinigung. Warenkorb wird angepasst.",
            "Destatis veröffentlicht monatlich VPI/HVPI.",
            "Falle: VPI = Aktienindex oder nur Mieten."),
        "t3-ezb" => F(t, "Die EZB ist die Zentralbank des Euroraums, vorrangiges Ziel Preisstabilität, unabhängig, Instrumente: Leitzinsen, Offenmarkt, Mindestreserve, in Krisen weitere Programme.",
            "Nicht: Arbeitsplätze als Vorrangziel wie dual mandate Fed (ähnlich, aber EZB-Primat Preisstabilität). Eurosystem mit nationalen NZBen.",
            "Zinserhöhung zur Bekämpfung zu hoher Inflation.",
            "Falle: EZB setzt den gesetzlichen Mindestlohn."),
        "t3-zinsen" => F(t, "Zins: Preis des Geldes/Kredits. Nominal vs. real (abzüglich Inflation). Leitzins beeinflusst Refinanzierung, nicht 1:1 jeden Kreditzins sofort.",
            "Zinseszins. EZB-Einlagefazilität vs. Kreditzins der Banken mit Marge.",
            "Nominal 5 %, Inflation 2 % → real ca. 3 %.",
            "Falle: Realzins immer = Leitzins."),
        "t3-konjunkturzyklus" => F(t, "Idealtypisch: Aufschwung, Hochkonjunktur, Abschwung, Tief. Indikatoren vorlaufend/gleichlaufend/nachlaufend.",
            "Zyklen unregelmäßig. Strukturbruch ≠ Zyklus.",
            "Auftragseingang steigt (vorlaufend), BIP steigt, Arbeitslosigkeit sinkt später.",
            "Falle: Zyklus mit exakt gleichen Jahreslängen."),
        "t3-geldpolitik" => F(t, "Expansiv: Zinsen senken, Liquidität erhöhen, Nachfrage stützen. Restriktiv: gegenteilig, Inflation dämpfen. Wirkt mit time lag, Zins- und Kreditkanal.",
            "Liquiditätsfalle, Angebotsschocks begrenzen Wirksamkeit. Unabhängigkeit der EZB.",
            "Inflation zu hoch → restriktiv. Unterauslastung + zu niedrige Inflation → expansiv.",
            "Falle: Expansive Geldpolitik senke immer sofort die Arbeitslosigkeit ohne Inflationsrisiko."),
        "t3-fiskalpolitik" => F(t, "Antizyklische Fiskalpolitik: in der Rezession mehr Staatsnachfrage/Defizit, im Boom gegenhalten (Schuldenbremse/EU-Regeln begrenzen). Built-in stabilizers: Steuern, Arbeitslosenversicherung.",
            "Crowding-out-Debatte. Time lags der Parlamente.",
            "Konjunkturprogramm in der Rezession, Überschüsse in der Hochphase.",
            "Falle: Prozyklisch sparen in der tiefen Rezession als 'immer antizyklisch' zu verkaufen."),
        "t3-nachhaltigkeit" => F(t, "Nachhaltigkeit: heutige Bedürfnisse ohne die der künftigen Generationen zu gefährden – ökologisch, ökonomisch, sozial (Drei-Säulen).",
            "Zielkonflikte transparent machen. Greenwashing vermeiden.",
            "Rechenzentrum: Effizienz, Stromherkunft, Arbeitsbedingungen, tragfähiges Geschäftsmodell.",
            "Falle: Nur Ökologie oder nur Rendite als 'nachhaltig'."),
        "t3-oeko-oeko-sozial" => F(t, "Ökologisch: Ressourcen/Klima. Ökonomisch: tragfähige Wertschöpfung. Sozial: Menschenwürde, Teilhabe, Gesundheit. Alle drei, nicht eine Alibi-Säule.",
            "CSR-Berichte, Lieferkette. Prüfung: Beispiele zuordnen.",
            "Faire Löhne (sozial), Gewinn (ökonomisch), Energie (ökologisch).",
            "Falle: Soziales als 'nicht prüfungsrelevant' weglassen."),
        "t3-verursacher" => F(t, "Verursacherprinzip: wer Schäden verursacht, trägt die Kosten (Internalisierung).",
            "Umweltrechtlicher Leitgedanke. Abgrenzung Gemeinlast und Vorsorge.",
            "CO2-Preis, Abwasserabgabe.",
            "Falle: Allgemeinheit zahlt immer (das wäre Gemeinlast)."),
        "t3-vorsorge" => F(t, "Vorsorgeprinzip: bereits bei wissenschaftlich unvollständigem, aber begründeten Besorgnispotenzial Maßnahmen, nicht erst nach Vollbeweis des Schadens.",
            "EU-Umweltrecht. Abwägung mit Verhältnismäßigkeit.",
            "Chemikalienbeschränkung trotz Restunsicherheit.",
            "Falle: Vorsorge = Nullrisiko um jeden Preis ohne Abwägung."),
        "t3-gemeinlast" => F(t, "Gemeinlastprinzip: die Allgemeinheit trägt Kosten, wenn Verursacher nicht heranziehbar oder politisch so entschieden (Altlasten, bestimmte Infrastruktur).",
            "Ergänzt, verdrängt Verursacher nicht als Leitbild.",
            "Sanierung historischer Altlast ohne greifbaren Verursacher aus Steuern.",
            "Falle: Gemeinlast als Standard für aktuelle Industrieemissionen."),
        "t3-green-it" => F(t, "Green IT: IKT ressourcenschonend (Effizienz, Hardware-Lebensdauer, Rechenzentrum, Homeoffice-Bilanz, Software-Bloat, Entsorgung/WEEE).",
            "Nicht nur 'Cloud ist immer grüner'. Messung (PUE), Beschaffung, Dark Mode allein reicht nicht.",
            "Virtualisierung, langlebige Geräte, Abschalten ungenutzter VMs.",
            "Falle: Jeder Online-Dienst sei automatisch ökologisch."),
        "t3-businessplan" => F(t, "Ein Businessplan beschreibt Vorhaben, Markt, Angebot, Organisation, Finanzen (Investition, Kapitalbedarf, Liquidität, Ertrag) und Risiken für Gründung und Kapitalgeber.",
            "Kein Roman: nachvollziehbare Annahmen. Deckungsbeitrag, Break-even.",
            "Helpdesk-SaaS-Plan mit 3-Jahres-GuV und Liquidität.",
            "Falle: Nur Logo und Vision ohne Zahlen."),
        "t3-usp" => F(t, "USP: der Nutzen, der das Angebot vom Wettbewerb glaubwürdig unterscheidet.",
            "Muss vom Kunden wahrgenommen werden, nicht nur intern. Kein Feature-Friedhof.",
            "Helpdesk mit Offline-Prüfungsmodus und nachvollziehbarer Prüfungsreife-Kennzahl.",
            "Falle: 'Wir sind freundlich' als einziger USP ohne Beleg."),
        "t3-marktanalyse" => F(t, "Markt- und Wettbewerbsanalyse: Marktgröße, Segmente, Wettbewerber, Einstiegsbarrieren, Trends (z. B. Porter-Fünf-Kräfte als Werkzeug).",
            "Primär- und Sekundärquellen. Keine Wunschzahlen.",
            "Anzahl FIAE-Azubis, bestehende Trainer-Apps, IHK-Termine.",
            "Falle: 'Es gibt keine Wettbewerber' ohne Recherche."),
        "t3-investitionsplan" => F(t, "Investitionsplan listet Anschaffungen (Anlagevermögen) mit Zeitpunkt und Betrag: Hardware, Lizenzen, Einrichtung, evtl. Entwicklungskosten aktivierbar nach Regeln.",
            "Trennung von Aufwand der laufenden Periode. AfA später in der Ertragsplanung.",
            "Jahr 1: 15 Laptops, Server, Softwarelizenzen.",
            "Falle: Gehälter als Investition im Anlagevermögen ohne Begründung."),
        "t3-kapitalbedarf" => F(t, "Kapitalbedarf = Anlage + laufende Mittel (Personal, Miete, Vorrat, Anlaufverluste) bis zum Cashflow-Break-even, plus Liquiditätsreserve.",
            "Eigen- vs. Fremdkapital. Unterfinanzierung ist ein Haupt-Gründungsrisiko.",
            "80.000 € Anlagen + 40.000 € Anlauf + 20.000 € Reserve.",
            "Falle: Nur den Laptoppreis als gesamten Kapitalbedarf."),
        "t3-liquiditaet" => F(t, "Liquiditätsplanung: Ein- und Auszahlungen zeitgenau, nicht Gewinn. Zahlungsunfähigkeit trotz Gewinn möglich (unbezahlt, Investitionen).",
            "Monatsscheiben, Kontokorrent, Debitorenlaufzeiten. Insolvenzrecht: Zahlungsunfähigkeit/Überschuldung juristischer Personen.",
            "Gewinn 10.000 €, aber Kunden zahlen in 90 Tagen, Löhne jetzt → Liquiditätsengpass.",
            "Falle: Liquidität = Gewinn."),
        "t3-rentabilitaetsvorschau" => F(t, "Rentabilitätsvorschau schätzt Erträge und Aufwendungen und den Gewinn, oft 3 Jahre, mit nachvollziehbaren Annahmen (Preise, Mengen, Kosten).",
            "Nicht identisch mit Liquidität. Sensitivität (was-wenn) zeigt Robustheit.",
            "Jahr 2: 120 Lizenzen × 49 € − Kosten = Gewinn.",
            "Falle: Nur ein 'wir werden reich'-Balken ohne Mengenannahme."),
        "t3-chancen-risiken" => F(t, "Chancen- und Risikoanalyse listet interne/externe Faktoren, bewertet Eintritt und Wirkung, nennt Gegenmaßnahmen (SWOT, Risikomatrix).",
            "Zu jedem wesentlichen Risiko eine Steuerung. Chancen nicht nur als Marketing.",
            "Risiko: IHK ändert Prüfungsform → Content-Versionierung. Chance: Pflicht-Digitalisierung der Ausbildung.",
            "Falle: Nur Chancen, Risiken 'haben wir nicht'."),
        _ => SynthesizeGeneric(t)
    };

    private static TeachingFact SynthesizeGeneric(TopicDef t)
        => F(t,
            $"{t.Title} ist ein eigenständiges, prüfungsrelevantes Thema der AP2 ({t.Part}) und muss mit Definition, Abgrenzung und einem Beispiel beherrscht werden.",
            $"Lernziel: {t.Title} erklären, typische Operatoren (Nennen, Beschreiben, Berechnen, Zuordnen) anwenden und häufige Verwechslungen vermeiden. Verknüpfen Sie das Thema mit angrenzenden Knoten im Themenbaum.",
            $"Prüfungstypisch: eine kurze Fallvignette zum Helpdesk- oder Ausbildungsbetrieb, in der {t.Title} angewendet wird.",
            $"Prüfungsfalle: {t.Title} nur als Überschrift wiederholen ohne Regel, Formel oder Abgrenzung.");
}
